import taf.ul.sc.tl_config as tl_config


class GenericOAMSelenium(object):
    """"""
    def __init__(self):
        self.selenium_webui = None

    def connect_to_webui_via_selenium(self):
        """
        Enabling virtual display, and than log in into WebEM.
        After finished session, "logout_via_selenium" and than "disable_virtual_display" should be called.
        :return: Session with WebEM.
        """
        self.selenium_webui.enable_virtual_display()
        self.login_via_selenium()

    def login_via_selenium(self, web_url=None, username=None, password=None):
        """
        Log in into WebEM. Has to be called after "enable_virtual_display".
        "logout_via_selenium" should be called after finished session.
        :param web_url: ip address of WebEM in format of https://...
        :param username: Username to WebEM
        :param password: Password to WebEM
        :return: Session with WebEM.
        """
        if not web_url:
            web_url = 'https://{}/'.format(
                tl_config.tl.gnbs[0].cu.oam_http_connection_details.addr)
        if not username:
            username = '{}'.format(tl_config.tl.gnbs[0].cu.oam_http_connection_details.username)
        if not password:
            password = '{}'.format(tl_config.tl.gnbs[0].cu.oam_http_connection_details.password)
        self.selenium_webui.login(web_url, username, password)

    def logout_via_selenium(self):
        """
        Log out from WebEM's session.
        :return: None.
        """
        self.selenium_webui.logout()

    def enable_virtual_display_via_selenium(self):
        """
        Do not display browser window on the screen.

        :return: None
        """
        self.selenium_webui.enable_virtual_display()

    def disable_virtual_display_via_selenium(self):
        """
        Disable virtual display. Should be called at the end of the keyword if "enable_virtual_display" was called.

        :return: None
        """
        self.selenium_webui.disable_virtual_display()
